static void ss_fe_2d_p4_basis_batch(size_t point_count, const double *reference_points,
                                    double *values, double *gradients) {
  size_t point;
  for (point = 0U; point < point_count; ++point) {
    ss_fe_2d_p4_basis_scalar(reference_points + point * 2U, values + point * 15U,
                             gradients == NULL ? NULL : gradients + point * 30U);
  }
}

