static void ss_fe_3d_p8_basis_scalar(const double *reference_point, double *values,
                                     double *gradients) {
  double lambda[4U] = {0.0};
  double factors[4U][9U] = {{0.0}};
  double derivatives[4U][9U] = {{0.0}};
  uint32_t barycentric_coordinate;
  uint32_t degree;
  size_t node;
  lambda[0U] = 1.0;
  for (barycentric_coordinate = 0U; barycentric_coordinate < 3U;
       ++barycentric_coordinate) {
    lambda[barycentric_coordinate + 1U] = reference_point[barycentric_coordinate];
    lambda[0U] -= reference_point[barycentric_coordinate];
  }
  for (barycentric_coordinate = 0U; barycentric_coordinate < 4U;
       ++barycentric_coordinate) {
    factors[barycentric_coordinate][0U] = 1.0;
    for (degree = 1U; degree <= 8U; ++degree) {
      uint32_t omitted;
      double derivative = 0.0;
      factors[barycentric_coordinate][degree] =
          factors[barycentric_coordinate][degree - 1U] *
          (8.0 * lambda[barycentric_coordinate] - (double)(degree - 1U)) /
          (double)degree;
      for (omitted = 0U; omitted < degree; ++omitted) {
        double product_value = 8.0;
        uint32_t factor;
        for (factor = 0U; factor < degree; ++factor) {
          if (factor != omitted) {
            product_value *= 8.0 * lambda[barycentric_coordinate] - (double)factor;
          }
        }
        for (factor = 2U; factor <= degree; ++factor) {
          product_value /= (double)factor;
        }
        derivative += product_value;
      }
      derivatives[barycentric_coordinate][degree] = derivative;
    }
  }
  for (node = 0U; node < 165U; ++node) {
    double value = 1.0;
    for (barycentric_coordinate = 0U; barycentric_coordinate < 4U;
         ++barycentric_coordinate) {
      value *= factors[barycentric_coordinate]
                      [ss_fe_3d_p8_barycentric[node * 4U + barycentric_coordinate]];
    }
    values[node] = value;
    if (gradients != NULL) {
      uint32_t coordinate;
      for (coordinate = 0U; coordinate < 3U; ++coordinate) {
        double positive = 1.0;
        double negative = 1.0;
        for (barycentric_coordinate = 0U; barycentric_coordinate < 4U;
             ++barycentric_coordinate) {
          const uint32_t alpha =
              ss_fe_3d_p8_barycentric[node * 4U + barycentric_coordinate];
          positive *= barycentric_coordinate == coordinate + 1U
                          ? derivatives[barycentric_coordinate][alpha]
                          : factors[barycentric_coordinate][alpha];
          negative *= barycentric_coordinate == 0U
                          ? derivatives[barycentric_coordinate][alpha]
                          : factors[barycentric_coordinate][alpha];
        }
        gradients[node * 3U + coordinate] = positive - negative;
      }
    }
  }
}

static void ss_fe_3d_p8_basis_batch(size_t point_count, const double *reference_points,
                                    double *values, double *gradients) {
  size_t point;
  for (point = 0U; point < point_count; ++point) {
    ss_fe_3d_p8_basis_scalar(reference_points + point * 3U, values + point * 165U,
                             gradients == NULL ? NULL : gradients + point * 495U);
  }
}

